  const ROMAN = ['I', 'II', 'III', 'IV', 'V', 'VI'];

  const fmtPct = v => String(Math.round(v * 1000) / 10).replace('.', ',') + '%';
  const fmtNum = v => String(Math.round(v * 10) / 10).replace('.', ',');

  function classifyAbTag(ab, kind, kit) {
    if (kind === 'tech') {
      const fx = kit && kit.tech && kit.tech.fx;
      if (fx === 'healAll' || fx === 'aquaTech' || fx === 'lcTech') return 'Восстановление';
      if (fx === 'shieldAll' || fx === 'gepardTech' || fx === 'fuxuanTech' || fx === 'fxTech' || fx === 'darknessTech') return 'Защита';
      if (fx === 'selfAtk' || fx === 'tingyunTech' || fx === 'bronyaTech' || fx === 'astaTech' || fx === 'yukongTech' || fx === 'jyTech' || fx === 'tzTech') return 'Усиление';
      if (fx === 'freezeAll' || fx === 'slowAll' || fx === 'fireVuln' || fx === 'pelaTech' || fx === 'sampoTech' || fx === 'hhTech' || fx === 'raTech' || fx === 'jlTech') return 'Ослабление';
      return 'Поддержка / Поле';
    }
    if (!ab) return 'Способность';
    const fx = Array.isArray(ab.fx) ? ab.fx : [];
    if (fx.some(f => f.k === 'dmg' || f.k === 'swing' || f.k === 'svarogMarked')) return TARGET_TAGS[ab.target] || 'Атака';
    if (fx.some(f => f.k === 'heal' || f.k === 'hot' || f.k === 'invig')) return 'Восстановление';
    if (fx.some(f => f.k === 'shield' || f.k === 'cover' || f.k === 'taunt' || (f.k === 'buff' && f.s === 'dr'))) return 'Защита';
    if (fx.some(f => f.k === 'debuff' || f.k === 'dot' || f.k === 'freeze' || f.k === 'imprison' || f.k === 'delay' || f.k === 'implant')) return 'Ослабление';
    return 'Поддержка';
  }

  function toughTextFor(ab, kind) {
    if (!ab || !Array.isArray(ab.fx)) return '';
    const dmg = ab.fx.find(f => f.k === 'dmg' || f.k === 'swing');
    if (!dmg) return '';
    const defMain = kind === 'basic' ? 10 : kind === 'enhanced' ? 20 : kind === 'skill' ? (ab.target === 'all' ? 10 : 20) : kind === 'ult' ? (ab.target === 'single' ? 30 : ab.target === 'blast' ? 30 : 20) : 10;
    const defAdj = kind === 'ult' ? 20 : 10;
    const main = dmg.tough || defMain;
    const adj = ab.target === 'blast' || dmg.adj != null ? (dmg.adjTough || defAdj) : 0;
    if (dmg.hits && dmg.hits > 1) return main + ' × ' + dmg.hits + ' отск.';
    return main + (adj ? ' (осн.) / ' + adj + ' (сосед.)' : '');
  }

  function contactMatrix(tag) {
    const eager = [], happy = [], bad = [];
    for (const [, fam] of Object.entries(H.CONTACT || {})) {
      const r = fam.react && fam.react[tag];
      if (r === 'eager') eager.push(fam.name);
      else if (r === 'happy') happy.push(fam.name);
      else if (r === 'angry' || r === 'scared') bad.push(fam.name + (r === 'angry' ? ' (злость)' : ' (испуг)'));
    }
    return { eager, happy, bad };
  }

  function formatExtras(g, charKey, kitId, list) {
    const tr = H.TRACES && H.TRACES[kitId];
    if (!tr || !list || !list.length) return [];
    const r = g && g.state && g.state.roster && g.state.roster[charKey];
    const eidCount = r ? (kitId === 'trail' || kitId === 'trail_p' ? (kitId === g.state.mcPath ? r.eid : (r.eidBy && r.eidBy[kitId]) || 0) : r.eid || 0) : 0;
    const out = [];
    for (const item of list) {
      const id = typeof item === 'string' ? item : item.id;
      const customNote = typeof item === 'object' && item.text ? item.text : null;
      if (id === 'a2' || id === 'a4' || id === 'a6') {
        const idx = id === 'a2' ? 0 : id === 'a4' ? 1 : 2;
        const b = tr.bonus && tr.bonus[idx];
        if (!b) continue;
        const st = g && r && g.traceNode ? g.traceNode(charKey, id) : null;
        const open = st ? st.cur > 0 : false;
        const phase = id === 'a2' ? 2 : id === 'a4' ? 4 : 6;
        out.push({
          id,
          kind: 'trace',
          title: b[0],
          tag: 'След Возвышения ' + phase,
          open,
          text: g ? g.fill(customNote || b[1]) : (customNote || b[1])
        });
      } else if (/^e[1-6]$/.test(id)) {
        const idx = +id.slice(1) - 1;
        const e = tr.eid && tr.eid[idx];
        if (!e) continue;
        const open = eidCount > idx;
        out.push({
          id,
          kind: 'eid',
          title: e[0],
          tag: 'Эйдолон ' + ROMAN[idx],
          open,
          text: g ? g.fill(customNote || e[1]) : (customNote || e[1])
        });
      }
    }
    return out;
  }

