          const d = ctx.ab.fx.find(f => f.k === 'dmg');
          return 'При 3 уровнях «Серии» наносит выбранному врагу ' + fmtPct(d.m) + ' электрического урона и снимает 25 стойкости (+1 ОД), сбрасывая «Серию».';
