        tag: 'Пробитие / Командная атака',
        extras: ['a2', 'a4', 'e4', 'e5', 'e6'],
        stats: ctx => [
          ['Бонус стойкости Навыка (Серия 3)', '+' + fmtPct(0.64 * ctx.talentMul) + ' к урону стойкости'],
          ['Командная «Цепочка атак»', '120% АТК выбранного союзника по цели и 40% по соседям при любом Пробитии!']
        ],
